#import "CHRootViewController.h"
#import "CHProfileStore.h"
#import "CHInstalledAppCatalog.h"
#import "CHAppLibraryController.h"
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>

static UIColor *CHGreen(void) { return [UIColor colorWithRed:.10 green:.78 blue:.48 alpha:1]; }
static UIColor *CHCard(void) { return [UIColor colorWithRed:.085 green:.10 blue:.115 alpha:1]; }
static UIColor *CHMuted(void) { return [UIColor colorWithRed:.62 green:.64 blue:.68 alpha:1]; }

@interface CHRootViewController () <UIDocumentPickerDelegate>
@property(nonatomic, strong) CHProfileStore *store;
@property(nonatomic, copy) NSArray<NSDictionary *> *applications;
@property(nonatomic, strong) UIScrollView *scrollView;
@property(nonatomic, strong) UIStackView *stack;
@end

@implementation CHRootViewController
- (void)viewDidLoad { [super viewDidLoad]; self.store = [CHProfileStore new]; self.title = @"Overview"; self.view.backgroundColor = [UIColor colorWithRed:.043 green:.051 blue:.059 alpha:1]; self.navigationController.navigationBarHidden = YES; [self buildInterface]; }
- (void)viewWillAppear:(BOOL)animated { [super viewWillAppear:animated]; self.navigationController.navigationBarHidden = YES; [self reloadApplications]; [self rebuildContent]; }
- (void)viewWillDisappear:(BOOL)animated { [super viewWillDisappear:animated]; if (self.navigationController.topViewController != self) self.navigationController.navigationBarHidden = NO; }
- (void)reloadApplications { self.applications = [CHInstalledAppCatalog thirdPartyApplications]; }
- (UILabel *)label:(NSString *)text size:(CGFloat)size weight:(UIFontWeight)weight color:(UIColor *)color { UILabel *label = [UILabel new]; label.text = text; label.textColor = color; label.font = [UIFont systemFontOfSize:size weight:weight]; label.numberOfLines = 0; return label; }
- (UIView *)card { UIView *view = [UIView new]; view.backgroundColor = CHCard(); view.layer.cornerRadius = 20; view.layer.borderWidth = 1; view.layer.borderColor = [UIColor colorWithWhite:1 alpha:.10].CGColor; return view; }
- (UIImageView *)icon:(UIImage *)image size:(CGFloat)size radius:(CGFloat)radius { UIImageView *view = [[UIImageView alloc] initWithImage:image]; view.translatesAutoresizingMaskIntoConstraints = NO; view.contentMode = UIViewContentModeScaleAspectFit; view.layer.cornerRadius = radius; view.layer.masksToBounds = YES; [view.widthAnchor constraintEqualToConstant:size].active = YES; [view.heightAnchor constraintEqualToConstant:size].active = YES; return view; }
- (UIButton *)button:(NSString *)title filled:(BOOL)filled { UIButton *button = [UIButton buttonWithType:UIButtonTypeSystem]; button.translatesAutoresizingMaskIntoConstraints = NO; [button setTitle:title forState:UIControlStateNormal]; [button setTitleColor:filled ? UIColor.whiteColor : CHGreen() forState:UIControlStateNormal]; button.titleLabel.font = [UIFont systemFontOfSize:17 weight:UIFontWeightSemibold]; button.backgroundColor = filled ? CHGreen() : UIColor.clearColor; button.layer.cornerRadius = 22; button.layer.borderWidth = filled ? 0 : 1.5; button.layer.borderColor = CHGreen().CGColor; [button.heightAnchor constraintEqualToConstant:48].active = YES; return button; }
- (void)addSection:(NSString *)title { UIView *spacer = [UIView new]; [spacer.heightAnchor constraintEqualToConstant:12].active = YES; [self.stack addArrangedSubview:spacer]; [self.stack addArrangedSubview:[self label:title size:22 weight:UIFontWeightBold color:UIColor.whiteColor]]; }

- (void)buildInterface {
    self.scrollView = [UIScrollView new]; self.scrollView.translatesAutoresizingMaskIntoConstraints = NO; self.scrollView.showsVerticalScrollIndicator = NO; [self.view addSubview:self.scrollView];
    self.stack = [[UIStackView alloc] initWithFrame:CGRectZero]; self.stack.translatesAutoresizingMaskIntoConstraints = NO; self.stack.axis = UILayoutConstraintAxisVertical; self.stack.spacing = 14; [self.scrollView addSubview:self.stack];
    UIView *bottom = [UIView new]; bottom.translatesAutoresizingMaskIntoConstraints = NO; bottom.backgroundColor = [UIColor colorWithRed:.055 green:.065 blue:.075 alpha:.98]; bottom.layer.borderColor = [UIColor colorWithWhite:1 alpha:.10].CGColor; bottom.layer.borderWidth = 1; [self.view addSubview:bottom];
    [NSLayoutConstraint activateConstraints:@[[self.scrollView.topAnchor constraintEqualToAnchor:self.view.topAnchor], [self.scrollView.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor], [self.scrollView.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor], [self.scrollView.bottomAnchor constraintEqualToAnchor:bottom.topAnchor], [bottom.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor], [bottom.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor], [bottom.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor], [bottom.heightAnchor constraintEqualToConstant:82], [self.stack.topAnchor constraintEqualToAnchor:self.scrollView.contentLayoutGuide.topAnchor constant:54], [self.stack.leadingAnchor constraintEqualToAnchor:self.scrollView.frameLayoutGuide.leadingAnchor constant:20], [self.stack.trailingAnchor constraintEqualToAnchor:self.scrollView.frameLayoutGuide.trailingAnchor constant:-20], [self.stack.bottomAnchor constraintEqualToAnchor:self.scrollView.contentLayoutGuide.bottomAnchor constant:-26]]];
    NSArray *titles = @[@"Overview", @"Apps", @"Profiles", @"Settings"]; NSArray *symbols = @[@"◉", @"▦", @"▱", @"⚙"]; UIStackView *tabs = [[UIStackView alloc] initWithFrame:CGRectZero]; tabs.translatesAutoresizingMaskIntoConstraints = NO; tabs.axis = UILayoutConstraintAxisHorizontal; tabs.distribution = UIStackViewDistributionFillEqually; [bottom addSubview:tabs];
    for (NSUInteger i = 0; i < titles.count; i++) { UIButton *tab = [UIButton buttonWithType:UIButtonTypeSystem]; tab.tag = i; [tab setTitle:[NSString stringWithFormat:@"%@\n%@", symbols[i], titles[i]] forState:UIControlStateNormal]; [tab setTitleColor:i == 0 ? CHGreen() : CHMuted() forState:UIControlStateNormal]; tab.titleLabel.font = [UIFont systemFontOfSize:13 weight:UIFontWeightMedium]; tab.titleLabel.numberOfLines = 2; tab.titleLabel.textAlignment = NSTextAlignmentCenter; [tab addTarget:self action:@selector(tabSelected:) forControlEvents:UIControlEventTouchUpInside]; [tabs addArrangedSubview:tab]; }
    [NSLayoutConstraint activateConstraints:@[[tabs.leadingAnchor constraintEqualToAnchor:bottom.leadingAnchor constant:8], [tabs.trailingAnchor constraintEqualToAnchor:bottom.trailingAnchor constant:-8], [tabs.topAnchor constraintEqualToAnchor:bottom.topAnchor constant:10], [tabs.bottomAnchor constraintEqualToAnchor:bottom.bottomAnchor constant:-8]]];
}

- (void)rebuildContent {
    if (!self.stack) return; for (UIView *view in self.stack.arrangedSubviews) [view removeFromSuperview];
    UIView *brand = [UIView new]; brand.translatesAutoresizingMaskIntoConstraints = NO; [brand.heightAnchor constraintEqualToConstant:72].active = YES; UIStackView *brandRow = [[UIStackView alloc] initWithFrame:CGRectZero]; brandRow.translatesAutoresizingMaskIntoConstraints = NO; brandRow.axis = UILayoutConstraintAxisHorizontal; brandRow.alignment = UIStackViewAlignmentCenter; brandRow.spacing = 12; UIImageView *logo = [self icon:[UIImage imageNamed:@"AppIcon1024"] size:58 radius:16]; UILabel *name = [self label:@"Chameleon" size:30 weight:UIFontWeightBold color:UIColor.whiteColor]; UIView *grow = [UIView new]; UILabel *status = [self label:@"●  Connected" size:15 weight:UIFontWeightSemibold color:CHGreen()]; status.textAlignment = NSTextAlignmentCenter; status.backgroundColor = [UIColor colorWithRed:.04 green:.15 blue:.11 alpha:1]; status.layer.cornerRadius = 14; status.layer.masksToBounds = YES; [brandRow addArrangedSubview:logo]; [brandRow addArrangedSubview:name]; [brandRow addArrangedSubview:grow]; [brandRow addArrangedSubview:status]; [brand addSubview:brandRow]; [NSLayoutConstraint activateConstraints:@[[brandRow.leadingAnchor constraintEqualToAnchor:brand.leadingAnchor], [brandRow.trailingAnchor constraintEqualToAnchor:brand.trailingAnchor], [brandRow.topAnchor constraintEqualToAnchor:brand.topAnchor], [brandRow.bottomAnchor constraintEqualToAnchor:brand.bottomAnchor], [status.widthAnchor constraintEqualToConstant:112], [status.heightAnchor constraintEqualToConstant:38]]]; [self.stack addArrangedSubview:brand];
    [self addCurrentProfileCard]; [self addFeatureCards]; [self addAppsSection]; UIButton *manage = [self button:@"⚙   Manage apps" filled:NO]; [manage addTarget:self action:@selector(openApps) forControlEvents:UIControlEventTouchUpInside]; [self.stack addArrangedSubview:manage];
}
- (NSDictionary *)applicationForProfile:(NSDictionary *)profile { NSString *bundleID = [profile[@"apps"] firstObject]; for (NSDictionary *app in self.applications) if ([app[@"bundleID"] isEqual:bundleID]) return app; return nil; }
- (void)addCurrentProfileCard {
    UIView *card = [self card]; NSDictionary *profile = self.store.activeProfile; NSDictionary *app = [self applicationForProfile:profile]; UILabel *heading = [self label:@"Current profile" size:20 weight:UIFontWeightSemibold color:UIColor.whiteColor]; UIImageView *appIcon = [self icon:app[@"icon"] ?: [UIImage systemImageNamed:@"app.fill"] size:76 radius:16]; appIcon.tintColor = CHGreen(); UILabel *profileName = [self label:profile ? profile[@"name"] : @"No profile selected" size:24 weight:UIFontWeightBold color:UIColor.whiteColor]; UILabel *running = [self label:profile ? @"●  Running" : @"Choose an app to begin" size:17 weight:UIFontWeightMedium color:profile ? CHGreen() : CHMuted()]; UIButton *open = [self button:@"Open profile" filled:YES]; open.enabled = profile && app; [open addTarget:self action:@selector(openActiveProfile) forControlEvents:UIControlEventTouchUpInside]; UIStackView *text = [[UIStackView alloc] initWithArrangedSubviews:@[profileName, running]]; text.axis = UILayoutConstraintAxisVertical; text.spacing = 8; UIStackView *row = [[UIStackView alloc] initWithArrangedSubviews:@[appIcon, text]]; row.translatesAutoresizingMaskIntoConstraints = NO; row.axis = UILayoutConstraintAxisHorizontal; row.alignment = UIStackViewAlignmentCenter; row.spacing = 18; [card addSubview:heading]; [card addSubview:row]; [card addSubview:open]; [NSLayoutConstraint activateConstraints:@[[heading.topAnchor constraintEqualToAnchor:card.topAnchor constant:22], [heading.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:22], [row.topAnchor constraintEqualToAnchor:heading.bottomAnchor constant:18], [row.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:22], [row.trailingAnchor constraintEqualToAnchor:card.trailingAnchor constant:-22], [open.topAnchor constraintEqualToAnchor:row.bottomAnchor constant:22], [open.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:22], [open.trailingAnchor constraintEqualToAnchor:card.trailingAnchor constant:-22], [open.bottomAnchor constraintEqualToAnchor:card.bottomAnchor constant:-22]]]; [self.stack addArrangedSubview:card];
}
- (void)addFeatureCards { UIStackView *row = [[UIStackView alloc] initWithFrame:CGRectZero]; row.axis = UILayoutConstraintAxisHorizontal; row.spacing = 12; row.distribution = UIStackViewDistributionFillEqually; row.translatesAutoresizingMaskIntoConstraints = NO; [row.heightAnchor constraintEqualToConstant:158].active = YES; NSDictionary *profile = self.store.activeProfile; NSDictionary *proxy = profile[@"proxy"]; NSDictionary *location = profile[@"location"]; [row addArrangedSubview:[self featureCard:@"◉" title:@"Proxy" detail:[proxy[@"enabled"] boolValue] ? @"ON" : @"OFF" color:CHGreen()]]; [row addArrangedSubview:[self featureCard:@"●" title:@"Location" detail:[location[@"enabled"] boolValue] ? (location[@"label"] ?: @"Configured") : @"Off" color:[UIColor colorWithRed:.15 green:.78 blue:.92 alpha:1]]]; [self.stack addArrangedSubview:row]; }
- (UIView *)featureCard:(NSString *)symbol title:(NSString *)title detail:(NSString *)detail color:(UIColor *)color { UIView *card = [self card]; UILabel *glyph = [self label:symbol size:27 weight:UIFontWeightBold color:color]; glyph.textAlignment = NSTextAlignmentCenter; glyph.backgroundColor = [color colorWithAlphaComponent:.15]; glyph.layer.cornerRadius = 27; glyph.layer.masksToBounds = YES; UILabel *name = [self label:title size:18 weight:UIFontWeightSemibold color:UIColor.whiteColor]; UILabel *value = [self label:detail size:16 weight:UIFontWeightMedium color:CHMuted()]; UIStackView *stack = [[UIStackView alloc] initWithArrangedSubviews:@[glyph, name, value]]; stack.translatesAutoresizingMaskIntoConstraints = NO; stack.axis = UILayoutConstraintAxisVertical; stack.spacing = 10; [card addSubview:stack]; [NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:16], [stack.trailingAnchor constraintEqualToAnchor:card.trailingAnchor constant:-16], [stack.topAnchor constraintEqualToAnchor:card.topAnchor constant:16], [stack.bottomAnchor constraintEqualToAnchor:card.bottomAnchor constant:-16], [glyph.widthAnchor constraintEqualToConstant:54], [glyph.heightAnchor constraintEqualToConstant:54]]]; return card; }
- (void)addAppsSection { [self addSection:@"Your apps"]; UIView *card = [self card]; UIStackView *rows = [[UIStackView alloc] initWithFrame:CGRectZero]; rows.translatesAutoresizingMaskIntoConstraints = NO; rows.axis = UILayoutConstraintAxisVertical; rows.spacing = 0; NSUInteger limit = MIN((NSUInteger)3, self.applications.count); for (NSUInteger i = 0; i < limit; i++) { NSDictionary *app = self.applications[i]; UIButton *row = [UIButton buttonWithType:UIButtonTypeSystem]; row.contentHorizontalAlignment = UIControlContentHorizontalAlignmentLeft; row.tag = i; [row addTarget:self action:@selector(appSelected:) forControlEvents:UIControlEventTouchUpInside]; UIImageView *icon = [self icon:app[@"icon"] ?: [UIImage systemImageNamed:@"app.fill"] size:48 radius:11]; UILabel *name = [self label:app[@"name"] ?: @"App" size:18 weight:UIFontWeightSemibold color:UIColor.whiteColor]; NSUInteger count = 0; for (NSDictionary *profile in self.store.profiles) if ([profile[@"apps"] containsObject:app[@"bundleID"]]) count++; UILabel *detail = [self label:[NSString stringWithFormat:@"%lu profile%@", (unsigned long)count, count == 1 ? @"" : @"s"] size:15 weight:UIFontWeightMedium color:CHMuted()]; UIStackView *text = [[UIStackView alloc] initWithArrangedSubviews:@[name, detail]]; text.axis = UILayoutConstraintAxisVertical; text.spacing = 3; UIStackView *line = [[UIStackView alloc] initWithArrangedSubviews:@[icon, text]]; line.axis = UILayoutConstraintAxisHorizontal; line.alignment = UIStackViewAlignmentCenter; line.spacing = 14; line.translatesAutoresizingMaskIntoConstraints = NO; [row addSubview:line]; UILabel *chevron = [self label:@"›" size:32 weight:UIFontWeightLight color:CHMuted()]; chevron.translatesAutoresizingMaskIntoConstraints = NO; [row addSubview:chevron]; [NSLayoutConstraint activateConstraints:@[[line.leadingAnchor constraintEqualToAnchor:row.leadingAnchor constant:16], [line.topAnchor constraintEqualToAnchor:row.topAnchor constant:12], [line.bottomAnchor constraintEqualToAnchor:row.bottomAnchor constant:-12], [chevron.trailingAnchor constraintEqualToAnchor:row.trailingAnchor constant:-18], [chevron.centerYAnchor constraintEqualToAnchor:row.centerYAnchor], [chevron.widthAnchor constraintEqualToConstant:20]]]; [rows addArrangedSubview:row]; if (i + 1 < limit) { UIView *divider = [UIView new]; divider.backgroundColor = [UIColor colorWithWhite:1 alpha:.10]; [divider.heightAnchor constraintEqualToConstant:1].active = YES; [rows addArrangedSubview:divider]; } } if (!limit) { UILabel *empty = [self label:@"No third-party apps detected" size:16 weight:UIFontWeightMedium color:CHMuted()]; empty.textAlignment = NSTextAlignmentCenter; [rows addArrangedSubview:empty]; [empty.heightAnchor constraintEqualToConstant:60].active = YES; } [card addSubview:rows]; [NSLayoutConstraint activateConstraints:@[[rows.leadingAnchor constraintEqualToAnchor:card.leadingAnchor], [rows.trailingAnchor constraintEqualToAnchor:card.trailingAnchor], [rows.topAnchor constraintEqualToAnchor:card.topAnchor], [rows.bottomAnchor constraintEqualToAnchor:card.bottomAnchor]]]; [self.stack addArrangedSubview:card]; }
- (void)tabSelected:(UIButton *)sender { if (sender.tag == 0) return; if (sender.tag == 1 || sender.tag == 2) [self openApps]; else [self showDiagnostics]; }
- (void)openApps { [self.navigationController pushViewController:[[CHAppLibraryController alloc] initWithStore:self.store] animated:YES]; }
- (void)appSelected:(UIButton *)sender { if (sender.tag < self.applications.count) [self openApps]; }
- (void)openActiveProfile { NSDictionary *profile = self.store.activeProfile; NSDictionary *app = [self applicationForProfile:profile]; if (!profile || !app) return; [self.navigationController pushViewController:[[CHProfileDetailController alloc] initWithStore:self.store application:app profileID:profile[@"id"]] animated:YES]; }
- (void)importBackup { UIDocumentPickerViewController *picker = [[UIDocumentPickerViewController alloc] initForOpeningContentTypes:@[UTTypeJSON, UTTypeData] asCopy:YES]; picker.delegate = self; [self presentViewController:picker animated:YES completion:nil]; }
- (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls { NSError *error = nil; if (urls.firstObject && [self.store importBackupFromURL:urls.firstObject error:&error]) [self rebuildContent]; else [self alert:@"Import Failed" message:error.localizedDescription ?: @"The selected backup could not be imported."]; }
- (void)showDiagnostics { UIDevice *device = UIDevice.currentDevice; device.batteryMonitoringEnabled = YES; NSString *message = [NSString stringWithFormat:@"Model: %@\niOS: %@\nVendor ID: %@\nInstalled apps: %lu\nProfiles: %lu\n\nProtected hardware identifiers are not collected.", device.model, device.systemVersion, device.identifierForVendor.UUIDString ?: @"Unavailable", (unsigned long)self.applications.count, (unsigned long)self.store.profiles.count]; [self alert:@"Device Information" message:message]; }
- (void)alert:(NSString *)title message:(NSString *)message { UIAlertController *alert = [UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert]; [alert addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleDefault handler:nil]]; [self presentViewController:alert animated:YES completion:nil]; }
@end
